import type { ReactNode } from 'react';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './navigation.css';

type Route = 'overview' | 'projects' | 'members';
export function Navigation({selected, onNavigate, onSettings, onHelp, projectIcon}: {selected: Route; onNavigate: (route: Route) => void; onSettings: () => void; onHelp: () => void; projectIcon: ReactNode}) {
  return <nav className="kui-layout kui-sidebar project-navigation" aria-label="Primary">
    <section className="kui-sidebar-section" aria-labelledby="workspace-section">
      <MenuHeader id="workspace-section">Workspace</MenuHeader>
      <MenuItem aria-current={selected === 'overview' ? 'page' : undefined} onClick={() => onNavigate('overview')}>Overview</MenuItem>
      <MenuItem icon={<span aria-hidden="true">{projectIcon}</span>} aria-current={selected === 'projects' ? 'page' : undefined} onClick={() => onNavigate('projects')}>Projects</MenuItem>
    </section>
    <section className="kui-sidebar-section" aria-labelledby="team-section">
      <MenuHeader id="team-section">Team</MenuHeader>
      <MenuItem aria-current={selected === 'members' ? 'page' : undefined} onClick={() => onNavigate('members')}>Members</MenuItem>
      <MenuItem disabled>Reports (unavailable)</MenuItem>
    </section>
    <section className="kui-sidebar-surface" aria-label="Workspace summary">
      <strong>Design workspace</strong>
      <p>12 projects · 8 members</p>
    </section>
    <footer className="navigation-footer" aria-label="Workspace actions">
      <button type="button" onClick={onSettings}>Settings</button>
      <button type="button" onClick={onHelp}>Help</button>
    </footer>
  </nav>;
}

